    UpdatedDate      DATETIMEOFFSET(7) NULL
);
GO

-- ---------- Testing.TestRuns ----------
CREATE TABLE Testing.TestRuns (
    TestRunId        INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    TestSuiteId      INT NOT NULL,
    Tool             VARCHAR(20) NOT NULL DEFAULT ('playwright'),
