-- Nullable-FK unique index (SQL Server treats multiple NULLs as distinct, so this
-- still allows unlinked Flow rows while enforcing 1:1 for linked ones)
CREATE UNIQUE INDEX UQ_FlowDefinitions_ProjectId ON Flow.FlowDefinitions(ProjectId);
GO

