-- =============================================================================
-- SECTION 7 — VIEWS (Phase 7: ลด Query ซ้ำซ้อนสำหรับหน้าที่เรียกบ่อย)
-- =============================================================================

-- สรุปสถิติต่อโปรเจกต์ (จำนวน Task/Milestone/สมาชิก) สำหรับหน้า Dashboard และรายงานภาพรวม
-- ลดการยิง COUNT(*) แยกหลายรอบต่อโปรเจกต์ในฝั่ง Application
GO
CREATE VIEW Project.vw_ProjectDashboardSummary AS
SELECT
    p.ProjectId,
    p.ProjectCode,
    p.ProjectName,
    p.ProjectOwnerId,
    p.Status,
    p.IsActive,
    (SELECT COUNT(*) FROM Project.Tasks t WHERE t.ProjectId = p.ProjectId) AS TotalTasks,
    (SELECT COUNT(*) FROM Project.Tasks t WHERE t.ProjectId = p.ProjectId AND t.Status = 'DONE') AS CompletedTasks,
    (SELECT COUNT(*) FROM Project.Milestones m WHERE m.ProjectId = p.ProjectId) AS TotalMilestones,
    (SELECT COUNT(*) FROM Project.ProjectMembers pm WHERE pm.ProjectId = p.ProjectId AND pm.IsActive = 1) AS MemberCount
FROM Project.Projects p;
GO

-- =============================================================================
-- SECTION 8 — STORED PROCEDURES (Phase 7: Operation ที่ซับซ้อน/เรียกบ่อย)
-- =============================================================================

-- คืนรายการ ProjectId ที่ @UserId เข้าถึงได้ (เป็นเจ้าของ หรือเป็นสมาชิกทีมที่ Active) — กติกาเดียวกับ
-- ProjectAccess.For(userId) ฝั่ง Backend (backend/Services/ProjectAccess.cs) ใช้สำหรับ Query/รายงานเฉพาะกิจนอกแอป
GO
CREATE PROCEDURE Core.sp_GetAccessibleProjectIds
    @UserId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT DISTINCT p.ProjectId
    FROM Project.Projects p
    LEFT JOIN Project.ProjectMembers pm ON pm.ProjectId = p.ProjectId AND pm.UserId = @UserId AND pm.IsActive = 1
    WHERE p.IsActive = 1 AND (p.ProjectOwnerId = @UserId OR pm.ProjectMemberId IS NOT NULL);
END;
GO

-- ลบโปรเจกต์แบบ Hard Delete พร้อมข้อมูลลูกทั้งหมด สำหรับใช้งานตรงจาก DB/สคริปต์ Ops เท่านั้น
-- (แอปจริงลบผ่าน EF ใน ProjectSoloService/ProjectTeamService.DeleteProjectAsync ซึ่งทำสิ่งเดียวกันนี้
-- อยู่แล้วผ่าน ON DELETE CASCADE ของ FK ส่วนใหญ่ + เคลียร์ตารางที่เป็น NoAction ด้วยโค้ด C# เอง)
GO
CREATE PROCEDURE Project.sp_DeleteProjectCascade
    @ProjectId INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRAN;
    BEGIN TRY
        DELETE FROM Project.StatusHistory WHERE ProjectId = @ProjectId
            OR TaskId IN (SELECT TaskId FROM Project.Tasks WHERE ProjectId = @ProjectId);
        DELETE FROM Project.Projects WHERE ProjectId = @ProjectId;
        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

-- =============================================================================
-- SECTION 9 — TRIGGERS (Phase 7: เท่าที่จำเป็นจริงๆ เพื่อไม่ให้กระทบ Performance)
-- =============================================================================

-- Sync Project.ProgressPercent อัตโนมัติจากค่าเฉลี่ย ProgressPercent ของ Task ระดับบนสุด (ไม่รวม Subtask)
-- ทุกครั้งที่มี Task ถูกเพิ่ม/แก้ไขในโปรเจกต์นั้น — กันไม่ให้ Progress ของโปรเจกต์เพี้ยนไปจาก Task จริง
GO
CREATE TRIGGER Project.Trg_UpdateProjectProgress
ON Project.Tasks
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH AffectedProjects AS (
        SELECT DISTINCT ProjectId FROM inserted
    )
    UPDATE p
    SET p.ProgressPercent = ISNULL(t.AvgProgress, 0),
        p.UpdatedDate = SYSDATETIMEOFFSET()
    FROM Project.Projects p
    INNER JOIN AffectedProjects ap ON ap.ProjectId = p.ProjectId
    OUTER APPLY (
        SELECT AVG(ProgressPercent) AS AvgProgress
        FROM Project.Tasks
        WHERE ProjectId = p.ProjectId AND ParentTaskId IS NULL
    ) t;
END;
GO

-- Denormalize Project.Projects.OwnerEmpId/OwnerName จาก Core.Users ให้เปิดตาราง Projects ตรงๆ
-- (ไม่ JOIN) แล้วรู้ทันทีว่าโปรเจกต์เป็นของใคร — Sync 2 ทิศทาง: ตอนตั้ง/เปลี่ยนเจ้าของ Project และ
-- ตอน User เจ้าของเปลี่ยนชื่อ/EmpId ของตัวเอง
GO
CREATE TRIGGER Project.Trg_SyncProjectOwnerDenorm
ON Project.Projects
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT UPDATE(ProjectOwnerId) RETURN;

    UPDATE p
    SET p.OwnerEmpId = u.EmpId,
        p.OwnerName = u.FullName
    FROM Project.Projects p
    INNER JOIN inserted i ON i.ProjectId = p.ProjectId
    INNER JOIN Core.Users u ON u.UserId = i.ProjectOwnerId;
END;
GO

CREATE TRIGGER Core.Trg_SyncProjectOwnerDenormFromUser
ON Core.Users
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT (UPDATE(EmpId) OR UPDATE(FullName)) RETURN;

    UPDATE p
    SET p.OwnerEmpId = i.EmpId,
        p.OwnerName = i.FullName
    FROM Project.Projects p
    INNER JOIN inserted i ON i.UserId = p.ProjectOwnerId;
END;
GO

-- ลบ Log เก่าอายุเกิน 90 วันอัตโนมัติทุกครั้งที่มีการเขียน Log ใหม่ (Batch เล็กๆ ครั้งละ 500 แถว กัน Table Lock)
-- ป้องกัน Core.AuditLogs โตไม่มีที่สิ้นสุดโดยไม่ต้องพึ่ง Job/Maintenance Plan แยกต่างหาก
GO
CREATE TRIGGER Core.Trg_AutoCleanup_AuditLogs
ON Core.AuditLogs
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    -- ลบ Log ที่เก่ากว่า 90 วัน
    -- ใช้ BATCH DELETE ขนาดเล็ก เพื่อป้องกัน Table Lock ตอนตารางมีขนาดใหญ่
    DELETE TOP (500) FROM Core.AuditLogs
    WHERE LogDate < DATEADD(DAY, -90, SYSDATETIMEOFFSET());
END;
GO

-- =============================================================================
-- SECTION 10 — REPORTING VIEWS (อ่านอย่างเดียว ไม่เปลี่ยนพฤติกรรมการเขียนข้อมูลใดๆ)
-- รวม JOIN/Projection ที่ Service หลายจุดเขียนซ้ำกันไว้ในที่เดียว ให้ Query จริงหรือ Report ในอนาคต
-- เรียกใช้ได้ตรงๆ แทนการต่อ JOIN เองยาวๆ ทุกครั้ง — ดู create_reporting_views.sql (root) สำหรับต้นฉบับ
-- =============================================================================

CREATE VIEW Core.vw_UserPermissionSummary AS
SELECT
    u.UserId,
    u.EmpId,
    u.FullName,
    u.UserLevel,
    u.IsSuperAdmin,
    u.IsSuspended,
    u.IsActive,
    u.IsOnline,
    u.DivisionName,
    u.DepartmentName,
    u.LastLoginDate,
    COUNT(perm.PermissionId)                                   AS SystemsGranted,
    SUM(CASE WHEN perm.CanView    = 1 THEN 1 ELSE 0 END)       AS CanViewCount,
    SUM(CASE WHEN perm.CanAdd     = 1 THEN 1 ELSE 0 END)       AS CanAddCount,
    SUM(CASE WHEN perm.CanEdit    = 1 THEN 1 ELSE 0 END)       AS CanEditCount,
    SUM(CASE WHEN perm.CanDelete  = 1 THEN 1 ELSE 0 END)       AS CanDeleteCount,
    SUM(CASE WHEN perm.CanApprove = 1 THEN 1 ELSE 0 END)       AS CanApproveCount,
    SUM(CASE WHEN perm.CanReject  = 1 THEN 1 ELSE 0 END)       AS CanRejectCount
FROM Core.Users u
LEFT JOIN Core.Permissions perm ON perm.UserId = u.UserId
GROUP BY
    u.UserId, u.EmpId, u.FullName, u.UserLevel, u.IsSuperAdmin, u.IsSuspended, u.IsActive,
    u.IsOnline, u.DivisionName, u.DepartmentName, u.LastLoginDate;
GO

CREATE VIEW Project.vw_ProjectOverview AS
SELECT
    p.ProjectId,
    p.ProjectCode,
    p.ProjectName,
    p.Description,
    p.ProjectTypeId,
    pt.TypeName                                                        AS ProjectTypeName,
    p.DivisionName,
    p.RequesterName,
    p.ProjectOwnerId,
    ownerUser.FullName                                                 AS OwnerName,
    p.CreatedBy,
    creatorUser.FullName                                               AS CreatedByName,
    p.Status,
    p.Priority,
    p.StartDate,
    p.EndDate,
    p.ProgressPercent,
    p.IsActive,
    p.CreatedDate,
    p.UpdatedDate,
    (SELECT COUNT(*) FROM Project.ProjectMembers pm WHERE pm.ProjectId = p.ProjectId) AS MemberCount,
    CASE WHEN EXISTS (SELECT 1 FROM Project.ProjectMembers pm2 WHERE pm2.ProjectId = p.ProjectId)
         THEN 'TEAM' ELSE 'SOLO' END                                   AS WorkType
FROM Project.Projects p
LEFT JOIN Project.ProjectTypes pt   ON pt.ProjectTypeId = p.ProjectTypeId
LEFT JOIN Core.Users ownerUser      ON ownerUser.UserId = p.ProjectOwnerId
LEFT JOIN Core.Users creatorUser    ON creatorUser.UserId = p.CreatedBy;
GO

CREATE VIEW Project.vw_ProjectOwnerStats AS
SELECT
    u.UserId,
    u.EmpId,
    u.FullName,
    u.UserLevel,
    u.DivisionName,
    u.DepartmentName,
    COUNT(p.ProjectId)          AS ProjectCount,
    MAX(p.CreatedDate)          AS LatestProjectDate
FROM Core.Users u
JOIN Project.Projects p ON p.ProjectOwnerId = u.UserId AND p.IsActive = 1
WHERE u.IsActive = 1 AND u.IsSuspended = 0
GROUP BY u.UserId, u.EmpId, u.FullName, u.UserLevel, u.DivisionName, u.DepartmentName;
GO

CREATE VIEW Project.vw_TaskProgress AS
SELECT
    t.ProjectId,
    COUNT(*)                                                    AS TotalTasks,
    SUM(CASE WHEN t.Status = 'DONE' THEN 1 ELSE 0 END)          AS CompletedTasks,
    CASE WHEN COUNT(*) = 0 THEN 0
         ELSE CAST(ROUND(100.0 * SUM(CASE WHEN t.Status = 'DONE' THEN 1 ELSE 0 END) / COUNT(*), 0) AS INT)
    END                                                          AS CompletionPercent
FROM Project.Tasks t
GROUP BY t.ProjectId;
GO

CREATE VIEW Flow.vw_FlowOverview AS
SELECT
    f.FlowDefinitionId,
    f.ProjectId,
    f.FlowCode,
    f.Name,
    f.Description,
    f.Status,
    f.WorkType,
    f.StartDate,
    f.EndDate,
    f.ProgressPercent,
    f.SystemType,
    f.ModuleList,
    f.DfdLevel,
    f.CreatedBy,
    creatorUser.FullName AS CreatedByName,
    f.IsActive,
    f.CreatedDate,
    f.UpdatedDate,
    (SELECT COUNT(*) FROM Flow.FlowDiagramRows r WHERE r.FlowDefinitionId = f.FlowDefinitionId)              AS TotalDiagramRows,
    (SELECT COUNT(DISTINCT r2.DiagramType) FROM Flow.FlowDiagramRows r2 WHERE r2.FlowDefinitionId = f.FlowDefinitionId) AS DiagramTypesFilled
FROM Flow.FlowDefinitions f
LEFT JOIN Core.Users creatorUser ON creatorUser.UserId = f.CreatedBy;
GO
